package deployment

import (
	"fmt"
	"strings"

	"github.com/stroppy-io/stroppy-cloud/internal/proto/cloud/v1/common"
	deploymentpb "github.com/stroppy-io/stroppy-cloud/internal/proto/cloud/v1/deployment"
)

// EngineFile is an extra, system-owned file an engine writes after its primary
// config (e.g. pg_hba.conf). StepID/StepOrder place it in the agent step list;
// ArtifactName is its render-preview artifact suffix and ArtifactLabel its
// "artifact" label. LockReason defaults to "<ArtifactName> is generated by the
// deployment renderer" when empty.
type EngineFile struct {
	StepID        string
	StepOrder     uint32
	ArtifactName  string
	ArtifactLabel string
	LockReason    string
	File          *common.File
}

// EngineComponent is the per-component rendering an engine produces. The two
// assemblers below turn it into the agent step list (RenderComponentDeployment)
// and the render-preview artifacts (RenderComponentPreview) so every engine
// emits the same shape: config dir, topology context, editable config, extra
// system files, install commands, systemd unit, activation, healthcheck.
type EngineComponent struct {
	Engine            string
	GlobalPriority    uint32
	NodePriority      uint32
	Dependencies      []string
	ConfigArtifactID  string
	ConfigFile        *common.File
	ConfigOrigin      deploymentpb.RenderArtifact_Origin
	DefaultConfigFile *common.File
	ExtraFiles        []EngineFile
	InstallCommands   []string
	ServiceFile       *common.File
	Healthcheck       string
}

// RenderComponentDeployment assembles the ordered agent step list for one
// component from its EngineComponent description.
func RenderComponentDeployment(ctx RenderContext, ec EngineComponent) *deploymentpb.ComponentDeployment {
	configDir := ConfigDir(ctx.Component.GetId())

	steps := make([]*deploymentpb.AgentStep, 0, 8+len(ec.InstallCommands)+len(ec.ExtraFiles))
	steps = append(steps,
		CreateDirStep("010_create_config_dir", 10, configDir, 0755),
		WriteFileStep("020_write_context", 20, ContextFile(ctx, ec.Dependencies)),
	)

	configStep := WriteFileStep("030_write_config", 30, ec.ConfigFile)
	configKind := "config_default"
	if ec.ConfigOrigin == deploymentpb.RenderArtifact_ORIGIN_USER_OVERRIDE {
		configKind = "config_override"
	}
	configStep.Labels = map[string]string{
		"kind":        configKind,
		"artifact_id": ec.ConfigArtifactID,
	}
	configStep.Tags = Tags("deployment", "config")
	steps = append(steps, configStep)

	for _, file := range ec.ExtraFiles {
		steps = append(steps, WriteFileStep(file.StepID, file.StepOrder, file.File))
	}

	installOrder := uint32(100)
	for _, command := range ec.InstallCommands {
		steps = append(steps, CallCmdStep(fmt.Sprintf("%03d_install", installOrder), installOrder, command))
		installOrder += 10
	}

	steps = append(steps,
		WriteFileStep("200_write_service", 200, ec.ServiceFile),
		CallCmdStep("210_reload_systemd", 210, "systemctl daemon-reload"),
		CallCmdStep("220_enable_start", 220, EnableStartServiceCommand(ctx.Component.GetId())),
		CallCmdStep("230_healthcheck", 230, ec.Healthcheck),
	)

	// Monitor phase: install + start the metrics/logs collectors for this
	// machine (node_exporter + DB exporter + vmagent + vector). No-op when the
	// server address is not stamped on the topology spec (e.g. previews).
	steps = append(steps, MonitorSteps(ctx)...)

	return &deploymentpb.ComponentDeployment{
		ComponentId:           ctx.Component.GetId(),
		NodeId:                ctx.Node.GetId(),
		GlobalPriority:        ec.GlobalPriority,
		NodePriority:          ec.NodePriority,
		DependsOnComponentIds: ec.Dependencies,
		Steps:                 steps,
		Status:                common.Status_STATUS_PENDING,
		Labels: MergeLabels(ctx.Component.GetLabels(), map[string]string{
			"engine": ctx.Component.GetEngine(),
			"role":   ctx.Component.GetRole(),
		}),
		Tags: ctx.Component.GetTags(),
	}
}

// RenderComponentPreview assembles the render-preview artifacts for one
// component from its EngineComponent description.
func RenderComponentPreview(ctx PreviewContext, ec EngineComponent) []*deploymentpb.RenderArtifact {
	configDir := ConfigDir(ctx.Component.GetId())

	artifacts := []*deploymentpb.RenderArtifact{
		DirArtifact(ctx, ec.Engine, "config-dir", &common.Dir{
			Info: &common.Dir_Info{
				Path: configDir,
				Mode: 0755,
			},
			CreateParents: true,
		}),
		FileArtifact(
			ctx,
			ec.Engine,
			ArtifactID(ctx.Component.GetId(), "topology.env"),
			PreviewContextFile(ctx, ec.Dependencies),
			deploymentpb.RenderArtifact_ORIGIN_SYSTEM,
			deploymentpb.RenderArtifact_MUTABILITY_READ_ONLY,
			"topology context is generated from topology and runtime state",
			"",
			map[string]string{"artifact": "context"},
		),
		FileArtifact(
			ctx,
			ec.Engine,
			ec.ConfigArtifactID,
			ec.ConfigFile,
			ec.ConfigOrigin,
			deploymentpb.RenderArtifact_MUTABILITY_EDITABLE,
			"",
			FileHash(ec.DefaultConfigFile),
			map[string]string{"artifact": "config"},
		),
		FileArtifact(
			ctx,
			ec.Engine,
			ArtifactID(ctx.Component.GetId(), "systemd.service"),
			ec.ServiceFile,
			deploymentpb.RenderArtifact_ORIGIN_SYSTEM,
			deploymentpb.RenderArtifact_MUTABILITY_READ_ONLY,
			"service unit is generated by the deployment renderer",
			"",
			map[string]string{"artifact": "service"},
		),
		RuntimeArtifact(ctx, ec.Engine, "runtime/private-address", "machine."+ctx.Node.GetId()+".endpoint.private.address"),
	}

	for _, file := range ec.ExtraFiles {
		lockReason := file.LockReason
		if lockReason == "" {
			lockReason = file.ArtifactName + " is generated by the deployment renderer"
		}
		label := file.ArtifactLabel
		if label == "" {
			label = "file"
		}
		artifacts = append(artifacts, FileArtifact(
			ctx,
			ec.Engine,
			ArtifactID(ctx.Component.GetId(), file.ArtifactName),
			file.File,
			deploymentpb.RenderArtifact_ORIGIN_SYSTEM,
			deploymentpb.RenderArtifact_MUTABILITY_READ_ONLY,
			lockReason,
			"",
			map[string]string{"artifact": label},
		))
	}

	installOrder := uint32(100)
	for _, command := range ec.InstallCommands {
		artifacts = append(artifacts, CommandArtifact(
			ctx,
			ec.Engine,
			ArtifactID(ctx.Component.GetId(), fmt.Sprintf("install/%03d", installOrder)),
			command,
			"package installation command is renderer-owned",
			map[string]string{"artifact": "install"},
		))
		installOrder += 10
	}
	artifacts = append(artifacts,
		CommandArtifact(ctx, ec.Engine, ArtifactID(ctx.Component.GetId(), "systemd/reload"), "systemctl daemon-reload", "systemd reload is renderer-owned", map[string]string{"artifact": "systemd_reload"}),
		CommandArtifact(ctx, ec.Engine, ArtifactID(ctx.Component.GetId(), "systemd/enable-start"), EnableStartServiceCommand(ctx.Component.GetId()), "systemd activation is renderer-owned", map[string]string{"artifact": "systemd_enable_start"}),
		CommandArtifact(ctx, ec.Engine, ArtifactID(ctx.Component.GetId(), "healthcheck"), ec.Healthcheck, "healthcheck command is renderer-owned", map[string]string{"artifact": "healthcheck"}),
	)

	return artifacts
}

func EnableStartServiceCommand(componentID string) string {
	service := ShellQuote(ServiceName(componentID))
	return fmt.Sprintf(`set -e
if ! systemctl enable --now %s; then
  echo "--- systemctl status %s ---"
  systemctl status --no-pager -l %s || true
  echo "--- journalctl %s ---"
  journalctl --no-pager --output=short-iso-precise -u %s -n 200 || true
  exit 1
fi
`, service, service, service, service, service)
}

// SimpleServiceUnit renders a Type=simple systemd unit that runs execStart and
// loads the component's topology.env. Engines that need bespoke ExecStartPre /
// init handling build their own unit instead.
func SimpleServiceUnit(componentID, role, configDir, execStart string) string {
	return fmt.Sprintf(`[Unit]
Description=Stroppy Cloud %s component %s
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
EnvironmentFile=%s/topology.env
ExecStart=%s
Restart=always
RestartSec=2

[Install]
WantedBy=multi-user.target
`, role, componentID, configDir, execStart)
}

// DataDir is the per-component persistent data directory an engine daemon uses.
func DataDir(componentID string) string {
	return "/var/lib/stroppy-cloud/" + componentID
}

// RunDir is the per-component runtime directory (sockets, pid files).
func RunDir(componentID string) string {
	return "/run/stroppy-cloud/" + componentID
}

// EngineServiceFile wraps a rendered unit body into the systemd unit File for a
// component.
func EngineServiceFile(componentID, unit string) *common.File {
	return &common.File{
		Info: &common.File_Info{
			Path:          "/etc/systemd/system/" + ServiceName(componentID) + ".service",
			Mode:          0644,
			CreateParents: true,
		},
		Content: &common.File_Text{Text: unit},
	}
}

// PreviewContextFile renders the topology.env preview using a runtime
// placeholder for the private address (the real value resolves after
// infrastructure provisioning).
func PreviewContextFile(ctx PreviewContext, dependencies []string) *common.File {
	var b strings.Builder
	fmt.Fprintf(&b, "COMPONENT_ID=%s\n", ShellValue(ctx.Component.GetId()))
	fmt.Fprintf(&b, "NODE_ID=%s\n", ShellValue(ctx.Node.GetId()))
	fmt.Fprintf(&b, "ENGINE=%s\n", ShellValue(ctx.Component.GetEngine()))
	fmt.Fprintf(&b, "ROLE=%s\n", ShellValue(ctx.Component.GetRole()))
	if len(dependencies) > 0 {
		fmt.Fprintf(&b, "DEPENDS_ON=%s\n", ShellValue(strings.Join(dependencies, ",")))
	}
	fmt.Fprintf(&b, "ENDPOINT_PRIVATE_ADDRESS=%s\n", ShellValue("${runtime.machine."+ctx.Node.GetId()+".endpoint.private.address}"))
	for _, target := range previewDependencyTargets(ctx, dependencies) {
		writeDependencyTargetEnv(&b, target)
	}

	return &common.File{
		Info: &common.File_Info{
			Path:          ConfigDir(ctx.Component.GetId()) + "/topology.env",
			Mode:          0644,
			CreateParents: true,
		},
		Content: &common.File_Text{Text: b.String()},
	}
}

func previewDependencyTargets(ctx PreviewContext, dependencies []string) []RuntimeTarget {
	dependencySet := make(map[string]struct{}, len(dependencies))
	for _, dependency := range dependencies {
		dependencySet[dependency] = struct{}{}
	}

	targets := make([]RuntimeTarget, 0)
	seen := map[string]struct{}{}
	for _, connection := range ctx.Topology.OutgoingConnections(ctx.Component.GetId()) {
		target, ok := ctx.Topology.Component(connection.GetToComponentId())
		if !ok || target.GetId() == ctx.Component.GetId() {
			continue
		}
		if len(dependencySet) > 0 {
			if _, ok := dependencySet[target.GetId()]; !ok {
				continue
			}
		}
		node, ok := ctx.Topology.NodeForComponentID(target.GetId())
		if !ok {
			continue
		}
		endpointName := connection.GetEndpointName()
		if endpointName == "" {
			endpointName = "private"
		}
		key := target.GetId() + "\x00" + endpointName + "\x00" + fmt.Sprint(connection.GetPort())
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		targets = append(targets, RuntimeTarget{
			ComponentID:  target.GetId(),
			NodeID:       node.GetId(),
			Engine:       target.GetEngine(),
			Role:         target.GetRole(),
			EndpointName: endpointName,
			Address:      "${runtime.machine." + node.GetId() + ".endpoint.private.address}",
			Port:         connection.GetPort(),
		})
	}
	sortRuntimeTargets(targets)
	return targets
}

// FileArtifact builds a KIND_FILE render artifact owned by the named engine.
func FileArtifact(
	ctx PreviewContext,
	engine string,
	artifactID string,
	file *common.File,
	origin deploymentpb.RenderArtifact_Origin,
	mutability deploymentpb.RenderArtifact_Mutability,
	lockReason string,
	baseHash string,
	labels map[string]string,
) *deploymentpb.RenderArtifact {
	return &deploymentpb.RenderArtifact{
		Id:           artifactID,
		ComponentId:  ctx.Component.GetId(),
		Kind:         deploymentpb.RenderArtifact_KIND_FILE,
		Origin:       origin,
		Mutability:   mutability,
		LockReason:   lockReason,
		Artifact:     &deploymentpb.RenderArtifact_File{File: file},
		RendererName: engine,
		BaseHash:     baseHash,
		Labels: MergeLabels(map[string]string{
			"engine": engine,
			"role":   ctx.Component.GetRole(),
		}, labels),
		Tags: Tags("render", engine, "file"),
	}
}

// CommandArtifact builds a KIND_COMMAND render artifact owned by the named engine.
func CommandArtifact(ctx PreviewContext, engine, artifactID, script, lockReason string, labels map[string]string) *deploymentpb.RenderArtifact {
	return &deploymentpb.RenderArtifact{
		Id:           artifactID,
		ComponentId:  ctx.Component.GetId(),
		Kind:         deploymentpb.RenderArtifact_KIND_COMMAND,
		Origin:       deploymentpb.RenderArtifact_ORIGIN_SYSTEM,
		Mutability:   deploymentpb.RenderArtifact_MUTABILITY_READ_ONLY,
		LockReason:   lockReason,
		Artifact:     &deploymentpb.RenderArtifact_Cmd{Cmd: ShellCmd(script)},
		RendererName: engine,
		Labels: MergeLabels(map[string]string{
			"engine": engine,
			"role":   ctx.Component.GetRole(),
		}, labels),
		Tags: Tags("render", engine, "command"),
	}
}

// DirArtifact builds a KIND_DIRECTORY render artifact owned by the named engine.
func DirArtifact(ctx PreviewContext, engine, name string, dir *common.Dir) *deploymentpb.RenderArtifact {
	return &deploymentpb.RenderArtifact{
		Id:           ArtifactID(ctx.Component.GetId(), name),
		ComponentId:  ctx.Component.GetId(),
		Kind:         deploymentpb.RenderArtifact_KIND_DIRECTORY,
		Origin:       deploymentpb.RenderArtifact_ORIGIN_SYSTEM,
		Mutability:   deploymentpb.RenderArtifact_MUTABILITY_READ_ONLY,
		LockReason:   "filesystem layout is renderer-owned",
		Artifact:     &deploymentpb.RenderArtifact_Dir{Dir: dir},
		RendererName: engine,
		Labels: map[string]string{
			"engine":   engine,
			"role":     ctx.Component.GetRole(),
			"artifact": "directory",
		},
		Tags: Tags("render", engine, "directory"),
	}
}

// RuntimeArtifact builds a KIND_RUNTIME_VALUE render artifact owned by the named engine.
func RuntimeArtifact(ctx PreviewContext, engine, name, runtimeValue string) *deploymentpb.RenderArtifact {
	return &deploymentpb.RenderArtifact{
		Id:           ArtifactID(ctx.Component.GetId(), name),
		ComponentId:  ctx.Component.GetId(),
		Kind:         deploymentpb.RenderArtifact_KIND_RUNTIME_VALUE,
		Origin:       deploymentpb.RenderArtifact_ORIGIN_RUNTIME,
		Mutability:   deploymentpb.RenderArtifact_MUTABILITY_RUNTIME_ONLY,
		LockReason:   "resolved after infrastructure provisioning",
		Artifact:     &deploymentpb.RenderArtifact_RuntimeValue{RuntimeValue: runtimeValue},
		RendererName: engine,
		Labels: map[string]string{
			"engine":   engine,
			"role":     ctx.Component.GetRole(),
			"artifact": "runtime_value",
		},
		Tags: Tags("render", engine, "runtime"),
	}
}
